async function openVideoCompression(target,ratio=0){selectOnlyMedia(target);activeCompressionTarget=target;$('#videoCompressionPanel').hidden=false;$('#imageEffectPanel').hidden=true;$('#runVideoCompression').disabled=false;$('#videoCompressionSource').textContent='正在读取视频时长和码率…';$('#videoEstimatedSize').textContent='—';beginMediaTask(`正在分析 ${target.image.name}`,`$ ffprobe "${target.file.sourcePath} :: ${target.image.entryPath}"`);try{const probe=await window.api.probeOfficeVideo({sourcePath:target.file.sourcePath,entryPath:target.image.entryPath});target.image.probe=probe;let video=2095,audio=128;if(ratio){const total=probe.duration?probe.bytes*ratio*8/probe.duration/1000:2223;video=Math.max(64,Math.round(total-audio));}$('#videoBitrate').value=video;$('#audioBitrate').value=audio;$('#videoCompressionSource').textContent=`${target.image.name} · ${probe.width}×${probe.height} · ${probe.duration.toFixed(1)} 秒 · 当前 ${fmt(probe.bytes)}`;updateCompressionEstimate();updateMediaTask(100,`INFO · ${probe.videoCodec}/${probe.audioCodec} · ${probe.sourceBitrate} kbps`);}catch(error){$('#videoCompressionSource').textContent=`读取失败：${error.message}`;$('#runVideoCompression').disabled=true;updateMediaTask(0,`ERROR · ${error.message}`);}}
