function renderSanitizationWorkspace(){
  const selected=sanitizationFiles.filter(file=>file.batchSelected);
  $('#sanitizeFileCount').textContent=`${sanitizationFiles.length} 个`;
  $('#clearSanitizeFiles').disabled=!sanitizationFiles.length;
  $('#sanitizeSelectedCount').textContent=`已选择 ${selected.length} 个文件`;
  $('#sanitizeBatchActions').hidden=!selected.length;
  $('#sanitizeSelectAll').checked=Boolean(sanitizationFiles.length)&&selected.length===sanitizationFiles.length;
  $('#sanitizeSelectAll').indeterminate=selected.length>0&&selected.length<sanitizationFiles.length;
  $('#sanitizeFileList').innerHTML=sanitizationFiles.map((file,index)=>`<div class="sanitize-file ${index===activeSanitizationIndex?'active':''}"><label class="sanitize-file-check" title="选择用于批量操作"><input type="checkbox" data-sanitize-select="${index}" ${file.batchSelected?'checked':''}></label><button type="button" data-sanitize-file="${index}"><span class="file-type-icon">${extensionLabel(file)}</span><span class="sanitize-file-copy"><strong>${esc(file.name)}</strong><small>${esc(file.sourcePath)}</small><span>${file.error?'解析失败':`${file.items.length} 项可脱敏${file.hasRevisions?' · 修订中':''}`}</span></span></button></div>`).join('');
  $$('#sanitizeFileList [data-sanitize-file]').forEach(button=>button.onclick=()=>{activeSanitizationIndex=Number(button.dataset.sanitizeFile);$('#watermarkResults').hidden=true;renderSanitizationWorkspace();});
  $$('#sanitizeFileList [data-sanitize-file]').forEach(button=>button.oncontextmenu=event=>{event.preventDefault();const index=Number(button.dataset.sanitizeFile),file=sanitizationFiles[index];showDocumentFileMenu(file.sourcePath,()=>{sanitizationFiles.splice(index,1);activeSanitizationIndex=Math.min(activeSanitizationIndex,Math.max(0,sanitizationFiles.length-1));renderSanitizationWorkspace();});});
  $$('#sanitizeFileList [data-sanitize-select]').forEach(input=>input.onchange=()=>{sanitizationFiles[Number(input.dataset.sanitizeSelect)].batchSelected=input.checked;renderSanitizationWorkspace();});
  renderSanitizationDetail();
}
async function addSanitizationFiles(){const selected=await window.api.pickWatermarkFiles(),existing=new Set(sanitizationFiles.map(file=>file.sourcePath)),incoming=selected.filter(file=>!existing.has(file));if(!incoming.length)return;setStatus('正在检查新增文件');const inspected=await window.api.inspectSanitization(incoming);sanitizationFiles.push(...inspected);activeSanitizationIndex=sanitizationFiles.length-inspected.length;renderSanitizationWorkspace();setStatus(`已添加 ${inspected.length} 个文件`);}
$('#sanitizeSelectAll').onchange=event=>{sanitizationFiles.forEach(file=>file.batchSelected=event.target.checked);renderSanitizationWorkspace();};
$('#clearSanitizeFiles').onclick=()=>{sanitizationFiles=[];activeSanitizationIndex=0;$('#watermarkResults').hidden=true;$('#revisionWarning').innerHTML='';renderSanitizationWorkspace();setStatus('已清空文件列表');};
function toggleFilePane(layoutSelector,button){const layout=$(layoutSelector),collapsed=layout.classList.toggle('files-collapsed'),label=collapsed?'展开文件栏':'折叠文件栏';button.textContent=collapsed?'›':'‹';button.title=label;button.setAttribute('aria-label',label);}
$('#toggleSanitizeFiles').onclick=event=>toggleFilePane('.sanitize-layout',event.currentTarget);
$('#toggleImageFiles').onclick=event=>toggleFilePane('.image-studio-layout',event.currentTarget);
$('#toggleEditorFiles').onclick=event=>toggleFilePane('.editor-layout',event.currentTarget);
function batchTargets(){return sanitizationFiles.filter(file=>file.batchSelected&&!file.error);}
$('#batchClearWatermarks').onclick=()=>{for(const file of batchTargets())for(const item of file.items.filter(item=>item.type==='watermark'))item.selected=true;renderSanitizationWorkspace();setStatus(`已为 ${batchTargets().length} 个文件标记清除水印，保存后生效`);};
$('#batchClearMetadata').onclick=()=>{for(const file of batchTargets())for(const item of file.items.filter(item=>item.type==='metadata')){if(item.originalValue===undefined)item.originalValue=item.detail||'';item.value='';}renderSanitizationWorkspace();setStatus(`已为 ${batchTargets().length} 个文件标记清除文件属性，保存后生效`);};
function renderSanitizationDetail(){
  const file=sanitizationFiles[activeSanitizationIndex];if(!file){$('#sanitizeComparisonList').innerHTML='';$('#sanitizeSave').disabled=true;$('#sanitizeSaveAs').disabled=true;return;}
  const byType=type=>file.items.filter(item=>item.type===type),watermarks=byType('watermark'),comments=byType('comment'),metadata=byType('metadata'),filesystem=byType('filesystem'),descriptionFields=new Set(['title','subject','keywords','category','comments']),description=metadata.filter(item=>descriptionFields.has(item.field)),origin=metadata.filter(item=>!descriptionFields.has(item.field)),editable=[...metadata,...filesystem];
  $('#revisionWarning').innerHTML=file.hasRevisions?`<div class="revision-warning"><strong>当前处于修订模式，建议打开源文件 → 审阅 → 接受所有修订</strong><span>检测到 ${file.revisionCount||0} 个修订标记；PreSalesX 不会擅自接受或拒绝修订。</span></div>`:'';
  for(const item of editable){if(item.originalValue===undefined)item.originalValue=item.detail||'';if(item.value===undefined)item.value=item.originalValue;}
  const itemHeading=item=>item.type==='watermark'?`<span class="sanitize-watermark-heading"><strong class="sanitize-item-name">${esc(item.label)}</strong><small><i aria-hidden="true">${item.subtype==='background'?'▧':item.subtype==='header'?'页':'T'}</i>${esc(item.detail||'未能读取水印内容')}</small></span>`:`<strong class="sanitize-item-name">${esc(item.label)}</strong>`;
  const comparisonRow=item=>{
    if(item.type==='metadata'||item.type==='filesystem'){const changed=String(item.value)!==String(item.originalValue),canClear=item.type==='metadata',cleared=canClear&&changed&&item.value==='',isTime=metadataTimeFields.has(item.field)||item.type==='filesystem',inputValue=isTime?toLocalDateTime(item.value):item.value,scope=item.type==='filesystem'?'filesystem':'metadata',formatHint=isTime?'保存时转换为 ISO 8601：YYYY-MM-DDTHH:mm:ss.sssZ':'';return `<div class="sanitize-compare-row sanitize-compare-item metadata-result ${changed?'changed':'kept'}" data-sanitize-row="${esc(item.id)}"><strong class="sanitize-item-name">${esc(item.label)}</strong><span class="sanitize-before-value"><small>${esc(item.originalValue||'<空>')}</small></span><span class="sanitize-after-value"><span class="sanitize-inline-controls"><span class="sanitize-editor"><input type="${isTime?'datetime-local':'text'}" ${isTime?'step="1" data-metadata-time="true"':''} data-${scope}-field="${esc(item.field)}" value="${esc(inputValue)}" placeholder="&lt;空&gt;" aria-label="${esc(item.label)}脱敏后的值" title="${formatHint}"></span><span class="sanitize-choice"><button type="button" class="${!changed?'selected':''}" data-restore-${scope}="${esc(item.field)}">保留原值</button>${canClear?`<button type="button" class="danger ${cleared?'selected':''}" data-clear-metadata="${esc(item.field)}">清空</button>`:''}</span><em>${cleared?'已清空':changed?'已修改':'保留'}</em></span></span></div>`;}
    return `<div class="sanitize-compare-row sanitize-compare-item ${item.selected?'changed':'kept'}" data-sanitize-row="${esc(item.id)}">${itemHeading(item)}<span class="sanitize-before-value"><small>${esc(item.detail||'<空>')}</small></span><span class="sanitize-after-value"><span class="sanitize-inline-controls"><small class="sanitize-result-preview">${item.selected?'&lt;已删除&gt;':esc(item.detail||'<空>')}</small><span class="sanitize-choice"><button type="button" class="${item.selected?'':'selected'}" data-set-removal="${esc(item.id)}" data-remove="false">保留</button><button type="button" class="danger ${item.selected?'selected':''}" data-set-removal="${esc(item.id)}" data-remove="true">删除</button></span><em>${item.selected?'将删除':'保留'}</em></span></span></div>`;
  };
  const group=(type,label,items)=>{const actions=type==='metadata'?'<button type="button" data-metadata-all="clear">全部清空</button><button type="button" data-metadata-all="restore">恢复全部</button>':type==='filesystem'?'<button type="button" data-filesystem-all="restore">恢复全部</button>':'<button type="button" data-removal-all="delete">全部删除</button><button type="button" data-removal-all="keep">全部保留</button>';return `<section class="sanitize-compare-group" data-sanitize-group="${type}"><header class="sanitize-compare-row"><strong>${label}<small>${items.length} 项</small></strong><span></span><span class="sanitize-group-actions">${items.length?actions:''}</span></header>${items.length?items.map(comparisonRow).join(''):'<p class="sanitize-none">未检测到此类内容</p>'}</section>`;};
  $('#sanitizeComparisonList').innerHTML=group('watermark','水印与背景',watermarks)+group('comment','批注',comments)+group('metadata','说明',description)+group('metadata','来源',origin)+group('filesystem','文件',filesystem);
  const changedItems=()=>file.items.filter(item=>item.type==='metadata'||item.type==='filesystem'?String(item.value)!==String(item.originalValue):item.selected);
  const updateControls=()=>{const changes=changedItems(),chosen=batchTargets(),targets=chosen.length?chosen:[file],totalChanges=targets.reduce((sum,target)=>sum+target.items.filter(item=>item.type==='metadata'||item.type==='filesystem'?String(item.value)!==String(item.originalValue):item.selected).length,0);$('#sanitizeChangeCount').textContent=chosen.length?`${chosen.length} 个文件 · ${totalChanges} 项变化`:`${changes.length} 项变化`;$('#sanitizeSave').disabled=!totalChanges||targets.some(target=>target.error);$('#sanitizeSaveAs').disabled=!totalChanges||targets.some(target=>target.error);};
  $$('[data-metadata-field],[data-filesystem-field]').forEach(input=>input.oninput=()=>{const scope=input.dataset.filesystemField?'filesystem':'metadata',field=input.dataset.filesystemField||input.dataset.metadataField,item=editable.find(value=>value.type===scope&&value.field===field),row=input.closest('[data-sanitize-row]'),nextValue=input.dataset.metadataTime?fromLocalDateTime(input.value):input.value,changed=String(nextValue)!==String(item.originalValue);item.value=nextValue;row.classList.toggle('changed',changed);row.classList.toggle('kept',!changed);row.querySelector(`[data-restore-${scope}]`).classList.toggle('selected',!changed);const clear=row.querySelector('[data-clear-metadata]');if(clear)clear.classList.toggle('selected',changed&&nextValue==='');row.querySelector('em').textContent=changed?(nextValue===''?'已清空':'已修改'):'保留';updateControls();});
  $$('#sanitizeComparisonList [data-clear-metadata]').forEach(button=>button.onclick=()=>{metadata.find(item=>item.field===button.dataset.clearMetadata).value='';renderSanitizationDetail();});
  $$('#sanitizeComparisonList [data-restore-metadata]').forEach(button=>button.onclick=()=>{const item=metadata.find(value=>value.field===button.dataset.restoreMetadata);item.value=item.originalValue;renderSanitizationDetail();});
  $$('#sanitizeComparisonList [data-restore-filesystem]').forEach(button=>button.onclick=()=>{const item=filesystem.find(value=>value.field===button.dataset.restoreFilesystem);item.value=item.originalValue;renderSanitizationDetail();});
  $$('#sanitizeComparisonList [data-set-removal]').forEach(button=>button.onclick=()=>{file.items.find(value=>value.id===button.dataset.setRemoval).selected=button.dataset.remove==='true';renderSanitizationDetail();});
  $$('#sanitizeComparisonList [data-metadata-all]').forEach(button=>button.onclick=()=>{metadata.forEach(item=>item.value=button.dataset.metadataAll==='clear'?'':item.originalValue);renderSanitizationDetail();});
  $$('#sanitizeComparisonList [data-filesystem-all]').forEach(button=>button.onclick=()=>{filesystem.forEach(item=>item.value=item.originalValue);renderSanitizationDetail();});
  $$('#sanitizeComparisonList [data-removal-all]').forEach(button=>button.onclick=()=>{const type=button.closest('[data-sanitize-group]').dataset.sanitizeGroup;file.items.filter(item=>item.type===type).forEach(item=>item.selected=button.dataset.removalAll==='delete');renderSanitizationDetail();});
  updateControls();
}
function renderWatermarkResult(result,action){const saved=action==='save',changes=(result.removed||0)+(result.modified||0)+(result.fileTimesModified||0);$('#watermarkSummary').textContent=result.status==='cleaned'?`${result.name} · 已${saved?'保存':'另存为'} · 共 ${changes} 项变化`:`${result.name||'当前文件'} · ${result.status==='unchanged'?'没有变化':'处理失败'}`;$('#watermarkResults').hidden=false;$('#watermarkResults').innerHTML=`<article class="watermark-result ${esc(result.status)}"><div><strong>${esc(result.name||result.sourcePath?.split(/[\\/]/).pop()||'当前文件')}</strong><small>${esc(result.destination||result.sourcePath||'')}</small><p>${result.status==='cleaned'?`已处理 ${changes} 项（删除内容 ${result.removed||0} 项，修改或清空文档属性 ${result.modified||0} 项，修改文件日期 ${result.fileTimesModified||0} 项），${saved?'原文件已更新':'已生成新文件'}`:result.status==='unchanged'?'脱敏前后没有变化':`处理失败：${esc(result.error||'不支持的文件')}`}</p>${result.destination?`<button data-output="${esc(result.destination)}">在文件夹中显示</button>`:''}</div><span class="result-status">${result.status==='cleaned'?'已完成':result.status==='unchanged'?'无变化':'需检查'}</span></article>`;const button=$('#watermarkResults [data-output]');if(button)button.onclick=()=>window.api.showFile(button.dataset.output);}
function sanitizationRequest(file,action){return {sourcePath:file.sourcePath,selectedIds:file.items.filter(item=>!['metadata','filesystem'].includes(item.type)&&item.selected).map(item=>item.id),metadataUpdates:Object.fromEntries(file.items.filter(item=>item.type==='metadata'&&String(item.value)!==String(item.originalValue)).map(item=>[item.field,item.value])),fileTimeUpdates:Object.fromEntries(file.items.filter(item=>item.type==='filesystem'&&String(item.value)!==String(item.originalValue)).map(item=>[item.field,item.value])),action};}
function requestHasChanges(request){return request.selectedIds.length||Object.keys(request.metadataUpdates).length||Object.keys(request.fileTimeUpdates).length;}
async function sanitizeCurrent(action){const current=sanitizationFiles[activeSanitizationIndex];if(!current)return;const chosen=batchTargets(),targets=chosen.length?chosen:[current],requests=targets.map(file=>sanitizationRequest(file,action)).filter(requestHasChanges);if(!requests.length)return;$('#sanitizeSave').disabled=true;$('#sanitizeSaveAs').disabled=true;setStatus(action==='save'?`正在保存 ${requests.length} 个文件`:`正在另存 ${requests.length} 个文件`);try{if(requests.length>1){const result=await window.api.sanitizeBatch({requests,action});if(!result){setStatus('已取消另存为');renderSanitizationWorkspace();return;}$('#watermarkResults').hidden=false;$('#watermarkResults').innerHTML=`<article class="watermark-result cleaned"><div><strong>${action==='save'?'批量保存完成':'批量脱敏包已生成'}</strong><small>${esc(result.destination||'')}</small><p>已处理 ${result.results.length} 个文件，共 ${result.results.reduce((sum,item)=>sum+(item.removed||0)+(item.modified||0),0)} 项变化。</p>${result.destination?`<button data-output="${esc(result.destination)}">在文件夹中显示</button>`:''}</div><span class="result-status">已完成</span></article>`;const output=$('#watermarkResults [data-output]');if(output)output.onclick=()=>window.api.showFile(output.dataset.output);if(action==='save'){const refreshed=await window.api.inspectSanitization(requests.map(item=>item.sourcePath));for(const item of refreshed){const index=sanitizationFiles.findIndex(file=>file.sourcePath===item.sourcePath);if(index>=0)sanitizationFiles[index]={...item,batchSelected:true};}}renderSanitizationWorkspace();setStatus(`批量脱敏完成 · ${result.results.length} 个文件`);return;}const file=targets[0],result=await window.api.sanitizeFile(requests[0]);if(!result){setStatus('已取消另存为');renderSanitizationDetail();return;}renderWatermarkResult({...result,name:file.name},action);if(action==='save'&&result.status==='cleaned'){const [updated]=await window.api.inspectSanitization([file.sourcePath]);sanitizationFiles[activeSanitizationIndex]={...updated,batchSelected:file.batchSelected};renderSanitizationWorkspace();}else renderSanitizationDetail();setStatus(result.status==='cleaned'?'脱敏处理完成':'当前文件没有变化');}catch(error){renderWatermarkResult({name:current.name,sourcePath:current.sourcePath,status:'error',error:error.message},action);renderSanitizationDetail();setStatus('脱敏处理失败');}}
$('#sanitizeSave').onclick=()=>sanitizeCurrent('save');
$('#sanitizeSaveAs').onclick=()=>sanitizeCurrent('saveAs');
$('#addSanitizeFiles').onclick=addSanitizationFiles;

function audit(){return project?.audit||{supplierStats:(project?.submissions||[]).map(item=>({id:item.id,supplier:item.supplier,zipName:item.zipName,fileCount:item.fileCount,totalSize:item.totalSize,totalSizeLabel:fmt(item.totalSize),parseErrors:item.files.filter(file=>file.parseError).length,types:Object.fromEntries([...new Set(item.files.map(file=>file.kind))].map(kind=>[kind,item.files.filter(file=>file.kind===kind).length]))})),identicalPackages:[],exactFiles:[],attributeMatches:[],similarityMatches:[],summary:{supplierCount:project?.submissions?.length||0,fileCount:allFiles().length,totalSizeLabel:fmt((project?.submissions||[]).reduce((sum,item)=>sum+item.totalSize,0)),identicalPackageGroups:0,exactFileGroups:0,attributeMatchGroups:0,similarityMatchGroups:0}};}
function kpi(label,value){return `<div class="kpi"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`;}
function typeChips(types={}){return Object.entries(types).map(([kind,count])=>`<span class="type-chip">${typeName(kind)} ${count}</span>`).join('');}
function fileButton(file,className='mini-file'){const key=file.key||`${file.submissionId||''}|${file.supplier}|${file.path||file.zipPath}`;return `<button class="${className}" data-file-key="${esc(key)}"><span class="file-kind">${typeName(file.kind)}</span><span title="${esc(file.path||file.zipPath)}">${esc(file.path||file.zipPath||file.name)}</span><small>${fmt(file.size)}</small></button>`;}
function bindFileButtons(root=document){root.querySelectorAll('[data-file-key]').forEach(button=>button.onclick=()=>openCompareFile(button.dataset.fileKey));}
function auditFileSet(groups=[]){return new Set(groups.flatMap(group=>group.files||[]).map(ref=>`${ref.supplier}|${ref.path}`));}
function keyMetadata(file){const a=file.attributes||{},office=[['作者',a.author],['最后一次保存者',a.lastEditor],['修订号',a.revision],['版本号',a.version||a.appVersion],['程序名称',a.application],['公司',a.company],['管理者',a.manager],['创建内容的时间',a.created],['最后一次保存的日期',a.modified]],pdf=[['作者',a.author],['标题',a.title],['主题',a.subject],['关键词',a.keywords],['创建程序',a.creator],['制作工具',a.producer],['创建时间',a.created],['修改时间',a.modified]],image=[['作者',a.author],['标题',a.title],['说明',a.description],['创建软件',a.software]];return ['word','excel','powerpoint'].includes(file.kind)?office:file.kind==='pdf'?pdf:file.kind==='image'?image:[['作者',a.author],['创建时间',a.created],['修改时间',a.modified]];}
function pathMarkup(value){const normalized=String(value||'').replace(/\\/g,'/'),index=normalized.lastIndexOf('/'),directory=index>=0?normalized.slice(0,index+1):'',name=index>=0?normalized.slice(index+1):normalized;return `<span class="path-directory">${esc(directory)}</span><span class="path-basename">${esc(name)}</span>`;}
function refMatchesFile(ref,file){return ref.supplier===file.supplier&&ref.path===file.zipPath;}
function fileIssues(file,data){const issues=[];for(const group of data.exactFiles||[]){if(!group.files.some(ref=>refMatchesFile(ref,file)))continue;const peers=group.files.filter(ref=>!refMatchesFile(ref,file)).map(ref=>`${ref.supplier} / ${ref.path}`);issues.push({label:'相同文件',level:'high',title:`与 ${peers.join('；')} 的文件内容完全相同（SHA-256：${group.sha256}）`});}for(const group of data.attributeMatches||[]){if(!group.files.some(ref=>refMatchesFile(ref,file)))continue;const peers=group.files.filter(ref=>!refMatchesFile(ref,file)).map(ref=>`${ref.supplier} / ${ref.path}`);issues.push({label:`${group.label}重复`,level:group.riskLevel==='高风险'?'high':group.riskLevel==='中风险'?'medium':'low',title:`与 ${peers.join('；')} 的${group.label}相同：${group.value}`});}for(const group of data.similarityMatches||[]){if(!group.files.some(ref=>refMatchesFile(ref,file)))continue;const peers=group.files.filter(ref=>!refMatchesFile(ref,file)).map(ref=>`${ref.supplier} / ${ref.path}`);issues.push({label:group.kind==='media'?'媒体指纹相同':'文本相似',level:group.kind==='media'?'high':'medium',title:`与 ${peers.join('；')} 存在${group.label}：${group.value}`});}return issues;}
function issueTags(issues){return issues.length?`<span class="file-issue-tags">${issues.map(issue=>`<span class="issue-tag ${issue.level}" title="${esc(issue.title)}">${esc(issue.label)}</span>`).join('')}</span>`:'';}
function supplierFileCard(file,index,data){const metadata=keyMetadata(file),issues=fileIssues(file,data);return `<details class="supplier-file-card" ${index===0?'open':''}><summary><span class="file-sequence">${index+1}</span><span class="supplier-file-path">${pathMarkup(file.zipPath)}${issueTags(issues)}</span><span class="supplier-file-size">${fmt(file.size)}</span></summary><div class="supplier-file-body"><div class="key-metadata">${metadata.map(([label,value])=>{const empty=value==null||value===''||value==='未提取到';return `<div><span>${esc(label)}</span><strong class="${empty?'is-empty':''}">${empty?'&lt;空&gt;':esc(value)}</strong></div>`;}).join('')}</div><button class="view-file-detail" data-file-key="${esc(file.key)}">查看更多与编辑</button></div></details>`;}
function supplierColumn(stat,sets,data){const submission=project.submissions.find(item=>item.id===stat.id);let files=(submission?.files||[]).map(file=>({...file,supplier:submission.supplier,submissionId:submission.id,key:`${submission.id}|${submission.supplier}|${file.zipPath}`}));if(supplierFilters.exact)files=files.filter(file=>sets.exact.has(`${file.supplier}|${file.zipPath}`));if(supplierFilters.attribute)files=files.filter(file=>sets.attribute.has(`${file.supplier}|${file.zipPath}`));return `<article class="supplier-column"><header class="supplier-head"><strong title="${esc(stat.zipName)}">${esc(stat.supplier)}</strong><small>${esc(stat.zipName)}</small></header><div class="supplier-metrics"><div><span>文件</span><strong>${files.length}${files.length!==stat.fileCount?` / ${stat.fileCount}`:''}</strong></div><div><span>文件大小</span><strong>${esc(stat.totalSizeLabel||fmt(stat.totalSize))}</strong></div><div><span>解析异常</span><strong>${stat.parseErrors||0}</strong></div></div><div class="supplier-types">${typeChips(stat.types)}</div><div class="supplier-files">${files.length?files.map((file,index)=>supplierFileCard(file,index,data)).join(''):'<div class="supplier-empty">没有符合当前筛选的文件</div>'}</div></article>`;}
function setSupplierFilesOpen(root,open){root.querySelectorAll('.supplier-file-card').forEach(card=>card.open=open);}
function renderOverview(){const data=audit(),root=$('#compareOverview'),identical=data.identicalPackages||[],sets={exact:auditFileSet(data.exactFiles),attribute:auditFileSet(data.attributeMatches)};root.innerHTML=`<div class="kpi-grid">${kpi('供应商',data.summary.supplierCount)}${kpi('文件总数',data.summary.fileCount)}${kpi('文件总大小',data.summary.totalSizeLabel)}${kpi('完全相同文件组',data.summary.exactFileGroups)}${kpi('属性重复组',data.summary.attributeMatchGroups)}</div>${identical.length?`<div class="alert-banner fatal"><span>!</span><div><strong>致命：发现 ${identical.length} 组内容结构完全一致的供应商 ZIP</strong><span>${identical.map(group=>group.suppliers.join(' ↔ ')).join('；')}</span></div></div>`:''}<div class="section-heading review-heading"><div><h2>文件审查</h2><p>每列代表一家供应商；默认展开首个文件，路径、关键字段与重复问题直接可见。</p></div><div class="review-controls"><label><input id="filterExactFiles" type="checkbox" ${supplierFilters.exact?'checked':''}> 仅查看相同文件</label><label><input id="filterAttributeFiles" type="checkbox" ${supplierFilters.attribute?'checked':''}> 仅查看属性重复文件</label><span class="compact-actions"><button data-expand-suppliers class="icon-button" title="全部展开" aria-label="全部展开">+</button><button data-collapse-suppliers class="icon-button" title="全部收起" aria-label="全部收起">−</button></span></div></div><div class="supplier-board" style="--supplier-count:${Math.max(1,data.supplierStats.length)}">${data.supplierStats.map(stat=>supplierColumn(stat,sets,data)).join('')}</div>`;bindFileButtons(root);$('#filterExactFiles').onchange=event=>{supplierFilters.exact=event.target.checked;renderOverview();};$('#filterAttributeFiles').onchange=event=>{supplierFilters.attribute=event.target.checked;renderOverview();};root.querySelector('[data-expand-suppliers]').onclick=()=>setSupplierFilesOpen(root,true);root.querySelector('[data-collapse-suppliers]').onclick=()=>setSupplierFilesOpen(root,false);}
function refsForGroup(group){return group.files.map(ref=>{const file=allFiles().find(item=>item.submissionId===String(ref.key||'').split('|')[0]&&item.zipPath===ref.path)||allFiles().find(item=>item.supplier===ref.supplier&&item.zipPath===ref.path);return file?fileButton(file,'match-file'):`<div class="match-file"><span class="supplier-tag">${esc(ref.supplier)}</span><span>${esc(ref.path)}</span><small>${fmt(ref.size)}</small></div>`;}).join('');}
function duplicateFileRow(group,ref){const file=allFiles().find(item=>item.supplier===ref.supplier&&item.zipPath===ref.path),key=file?.key||ref.key,detail=`${group.label}：${group.value}`;return `<button class="duplicate-file-row" data-file-key="${esc(key)}"><span class="duplicate-file-name"><span class="supplier-tag">${esc(ref.supplier)}</span>${pathMarkup(ref.path)}</span><span class="duplicate-evidence"><strong>${esc(detail)}</strong><small>${esc(group.riskLevel||'低风险')}</small></span></button>`;}
function renderAttributeReview(){const data=audit(),root=$('#compareAttributes'),cards=groups=>groups.map(group=>`<article class="match-card duplicate-card"><div class="match-head"><strong>${group.kind==='simhash'?'文本':group.kind==='media'?'媒体':typeName(group.kind)} · ${esc(group.label)}：${esc(group.value)}</strong><span class="risk-chip risk-${group.riskLevel==='高风险'?'high':group.riskLevel==='中风险'?'medium':'low'}">${esc(group.riskLevel||'低风险')} · ${group.suppliers.length} 家供应商</span></div><div class="duplicate-files">${group.files.map(ref=>duplicateFileRow(group,ref)).join('')}</div></article>`).join('');root.innerHTML=`<div class="notice">所有非空重复属性都会列出；完全相同文件、SimHash 与媒体指纹由系统自动审查，无需手动选择。</div><div class="section-heading"><div><h2>跨供应商属性重复</h2><p>按“字段 + 标准化值”分组；完整路径与重复数据并排展示。</p></div><span>${data.attributeMatches.length} 组</span></div><div class="match-list duplicate-list">${data.attributeMatches.length?cards(data.attributeMatches):'<div class="empty-state"><div><strong>没有发现跨供应商属性重复</strong></div></div>'}</div><div class="section-heading"><div><h2>文本与媒体相似性线索</h2><p>展示文本 SimHash 与 Office 内嵌图片、媒体指纹证据。</p></div><span>${data.similarityMatches.length} 组</span></div><div class="match-list duplicate-list">${data.similarityMatches.length?cards(data.similarityMatches):'<div class="empty-state"><div><strong>没有发现文本或媒体相似性线索</strong></div></div>'}</div>`;bindFileButtons(root);}
function renderOperationReport(){const root=$('#compareReport'),logs=project.operationLog||[];root.innerHTML=`<div class="section-heading"><div><h2>操作记录</h2><p>记录属性修改、删除、保存和另存为结果，可随项目与报告导出。</p></div><span>${logs.length} 条</span></div>${logs.length?`<table class="report-table"><thead><tr><th>时间</th><th>供应商</th><th>文件</th><th>操作</th><th>修改内容</th><th>结果</th></tr></thead><tbody>${logs.map(log=>`<tr><td>${esc(new Date(log.at||log.createdAt).toLocaleString())}</td><td>${esc(log.supplier||'本地文件')}</td><td>${esc(log.file||log.zipPath)}</td><td>${esc(log.action==='save'?'保存':'另存为')}</td><td>${esc([...(log.changedFields||[]),...(log.deletedFields||[]).map(field=>`删除 ${field}`)].join('、')||'—')}</td><td>${esc(log.destination||'')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state"><div><strong>尚无文件操作</strong><p>在右侧属性编辑器保存修改后，操作会记录在这里。</p></div></div>'}`;}
function renderActiveSection(){for(const name of ['overview','attributes','report'])$('#compare'+name[0].toUpperCase()+name.slice(1)).hidden=name!==activeSection;$$('.workspace-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.section===activeSection));if(activeSection==='overview')renderOverview();if(activeSection==='attributes')renderAttributeReview();if(activeSection==='report')renderOperationReport();}
function renderCompare(){const data=audit();$('#compareProjectName').textContent=project.name;$('#compareSummary').textContent=`${data.summary.supplierCount} 家供应商 · ${data.summary.fileCount} 个文件 · ${data.summary.exactFileGroups} 组相同文件 · ${data.summary.attributeMatchGroups} 组属性重复 · ${data.summary.similarityMatchGroups||0} 组相似性线索`;renderActiveSection();}
$$('.workspace-tab').forEach(tab=>tab.onclick=()=>{activeSection=tab.dataset.section;renderActiveSection();});
function openCompareFile(key){const file=findFile(key);if(!file)return;selectedFileKey=key;$('#propertyDrawer').hidden=false;$('#drawerContext').textContent=`${file.supplier} / ${file.name}`;renderFileDetail(file,$('#drawerDetail'));}
$('#closeDrawer').onclick=()=>$('#propertyDrawer').hidden=true;

function renderEditor(){const files=allFiles(),query=($('#fileSearch').value||'').toLowerCase(),filtered=files.filter(file=>(file.name+' '+file.zipPath).toLowerCase().includes(query));$('#editorSummary').textContent=`${files.length} 个本地文件 · 直接查看、修改或清理支持的文档属性`;$('#editorFileCount').textContent=`${filtered.length} 个`;$('#editorFileList').innerHTML=filtered.map(file=>`<button class="file-row ${selectedFileKey===file.key?'selected':''}" data-editor-file="${esc(file.key)}"><span class="file-type-icon">${extensionLabel(file.name)}</span><span><strong>${esc(file.name)}</strong><small class="file-row-path">${esc(file.sourcePath||file.zipPath)}</small><small>${fmt(file.size)}</small></span></button>`).join('');$$('[data-editor-file]').forEach(button=>{button.onclick=()=>{selectedFileKey=button.dataset.editorFile;renderEditor();const file=findFile(selectedFileKey);$('#editorDetail').className='editor-detail';renderFileDetail(file,$('#editorDetail'));};button.oncontextmenu=event=>{event.preventDefault();const file=findFile(button.dataset.editorFile);showDocumentFileMenu(file?.sourcePath,()=>{const submission=project?.submissions?.find(item=>item.id===file.submissionId);if(submission)submission.files=submission.files.filter(item=>item!==file&&item.sourcePath!==file.sourcePath);if(selectedFileKey===file.key)selectedFileKey='';renderEditor();});};});if(selectedFileKey){const file=findFile(selectedFileKey);if(file&&!$('#editorDetail .file-detail-sticky'))renderFileDetail(file,$('#editorDetail'));}}
async function addEditorFiles(){const selected=await window.api.pickFiles();if(!selected.length)return;inputFiles=[...new Set([...inputFiles,...selected])];showView('working');project=await window.api.analyze(inputFiles,{mode:'files'});selectedFileKey='';renderEditor();showView('editorWorkspace');}
$('#fileSearch').oninput=renderEditor;$('#addEditorFilesInline').onclick=addEditorFiles;
function setExplorerWidth(value){const layout=$('.editor-layout'),max=Math.max(280,layout.getBoundingClientRect().width*.55);layout.style.setProperty('--explorer-width',`${Math.min(max,Math.max(220,value))}px`);}
$('#editorSplitter').onpointerdown=event=>{const splitter=event.currentTarget,startX=event.clientX,startWidth=$('.explorer').getBoundingClientRect().width;splitter.setPointerCapture(event.pointerId);splitter.classList.add('dragging');splitter.onpointermove=move=>setExplorerWidth(startWidth+move.clientX-startX);splitter.onpointerup=()=>{splitter.classList.remove('dragging');splitter.onpointermove=null;splitter.onpointerup=null;};};
